-- Ontology knowledge: products, class hierarchy, and entity / asset / part-of views.
-- Generated by `python -m oag_semantic.platform_knowledge` from the ontology (knowledge/ontology/*.ttl and
-- knowledge/vocabulary.yaml, ADR 0047). Do not edit: change the ontology and regenerate.

-- Products and their grouping (skos:broader); product_metric = the governed metrics that measure
-- each product: its own, else those of the products under it ("total liquids" -> oil + water).
CREATE OR REPLACE TABLE OAG_FABLE.KNOWLEDGE.product (product_key STRING, metric STRING, broader STRING, definition STRING);
INSERT OVERWRITE INTO OAG_FABLE.KNOWLEDGE.product VALUES
  ('gas', 'actual_gas', NULL, NULL),
  ('gross_liquids', NULL, NULL, 'Oil and water together, as produced at the well.'),
  ('oil', 'actual_oil', 'gross_liquids', NULL),
  ('water', 'actual_water', 'gross_liquids', NULL);
CREATE OR REPLACE TABLE OAG_FABLE.KNOWLEDGE.product_synonym (synonym STRING, product_key STRING);
INSERT OVERWRITE INTO OAG_FABLE.KNOWLEDGE.product_synonym VALUES
  ('associated gas', 'gas'),
  ('crude', 'oil'),
  ('crude oil', 'oil'),
  ('gas', 'gas'),
  ('gross fluid', 'gross_liquids'),
  ('gross liquids', 'gross_liquids'),
  ('gross_liquids', 'gross_liquids'),
  ('liquids', 'gross_liquids'),
  ('oil', 'oil'),
  ('produced water', 'water'),
  ('total liquids', 'gross_liquids'),
  ('water', 'water');
CREATE OR REPLACE TABLE OAG_FABLE.KNOWLEDGE.product_metric (product_key STRING, metric STRING);
INSERT OVERWRITE INTO OAG_FABLE.KNOWLEDGE.product_metric VALUES
  ('gas', 'actual_gas'),
  ('gross_liquids', 'actual_oil'),
  ('gross_liquids', 'actual_water'),
  ('oil', 'actual_oil'),
  ('water', 'actual_water');
-- The class hierarchy (rdfs:subClassOf, transitive): (class, superclass).
CREATE OR REPLACE TABLE OAG_FABLE.KNOWLEDGE.ontology_class (class_name STRING, superclass_name STRING);
INSERT OVERWRITE INTO OAG_FABLE.KNOWLEDGE.ontology_class VALUES
  ('Facility', 'Asset'),
  ('Field', 'Asset'),
  ('Well', 'Asset');
-- Every mapped instance and its class, with the ontology's IRIs (from the R2RML mapping).
CREATE OR REPLACE VIEW OAG_FABLE.KNOWLEDGE.entity AS
SELECT CONCAT('https://example.org/oag/id/facility/', CAST(t.FACILITY_ID AS STRING), '/', REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CAST(t.FACILITY_TYPE AS STRING), '%', '%25'), ' ', '%20'), '!', '%21'), '"', '%22'), '#', '%23'), '$', '%24'), '&', '%26'), '''', '%27'), '(', '%28'), ')', '%29'), '*', '%2A'), '+', '%2B'), ',', '%2C'), '/', '%2F'), ':', '%3A'), ';', '%3B'), '<', '%3C'), '=', '%3D'), '>', '%3E'), '?', '%3F'), '@', '%40'), '[', '%5B'), ']', '%5D'), '^', '%5E'), '`', '%60'), '{', '%7B'), '|', '%7C'), '}', '%7D')) AS iri, 'Facility' AS class_name FROM OAG_FABLE.CANONICAL.facility t
UNION ALL
SELECT CONCAT('https://example.org/oag/id/field/', CAST(t.FIELD_ID AS STRING)) AS iri, 'Field' AS class_name FROM OAG_FABLE.CANONICAL.field t
UNION ALL
SELECT CONCAT('https://example.org/oag/id/well/', CAST(t.WELL_ID AS STRING)) AS iri, 'Well' AS class_name FROM OAG_FABLE.CANONICAL.well t;
-- Inheritance: an asset is an entity whose class is a subclass of Asset.
CREATE OR REPLACE VIEW OAG_FABLE.KNOWLEDGE.asset AS
SELECT e.iri, e.class_name FROM OAG_FABLE.KNOWLEDGE.entity e
JOIN OAG_FABLE.KNOWLEDGE.ontology_class c ON c.class_name = e.class_name AND c.superclass_name = 'Asset';
-- Direct part-of links: the subproperties of oag:partOf, as the mapping defines them.
CREATE OR REPLACE VIEW OAG_FABLE.KNOWLEDGE.part_of_edge AS
SELECT CONCAT('https://example.org/oag/id/well/', CAST(t.WELL_ID AS STRING)) AS part, CONCAT('https://example.org/oag/id/facility/', CAST(p.FACILITY_ID AS STRING), '/', REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CAST(p.FACILITY_TYPE AS STRING), '%', '%25'), ' ', '%20'), '!', '%21'), '"', '%22'), '#', '%23'), '$', '%24'), '&', '%26'), '''', '%27'), '(', '%28'), ')', '%29'), '*', '%2A'), '+', '%2B'), ',', '%2C'), '/', '%2F'), ':', '%3A'), ';', '%3B'), '<', '%3C'), '=', '%3D'), '>', '%3E'), '?', '%3F'), '@', '%40'), '[', '%5B'), ']', '%5D'), '^', '%5E'), '`', '%60'), '{', '%7B'), '|', '%7C'), '}', '%7D')) AS whole, 'atFacility' AS property FROM OAG_FABLE.CANONICAL.well t JOIN OAG_FABLE.CANONICAL.facility p ON t.FACILITY_ID = p.FACILITY_ID
UNION ALL
SELECT CONCAT('https://example.org/oag/id/facility/', CAST(t.FACILITY_ID AS STRING), '/', REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CAST(t.FACILITY_TYPE AS STRING), '%', '%25'), ' ', '%20'), '!', '%21'), '"', '%22'), '#', '%23'), '$', '%24'), '&', '%26'), '''', '%27'), '(', '%28'), ')', '%29'), '*', '%2A'), '+', '%2B'), ',', '%2C'), '/', '%2F'), ':', '%3A'), ';', '%3B'), '<', '%3C'), '=', '%3D'), '>', '%3E'), '?', '%3F'), '@', '%40'), '[', '%5B'), ']', '%5D'), '^', '%5E'), '`', '%60'), '{', '%7B'), '|', '%7C'), '}', '%7D')) AS part, CONCAT('https://example.org/oag/id/field/', CAST(t.FIELD_ID AS STRING)) AS whole, 'inField' AS property FROM OAG_FABLE.CANONICAL.facility t
UNION ALL
SELECT CONCAT('https://example.org/oag/id/well/', CAST(t.WELL_ID AS STRING)) AS part, CONCAT('https://example.org/oag/id/field/', CAST(t.FIELD_ID AS STRING)) AS whole, 'inField' AS property FROM OAG_FABLE.CANONICAL.well t;
-- oag:partOf is transitive: the closure, as joins up to the longest chain the mapping allows.
CREATE OR REPLACE VIEW OAG_FABLE.KNOWLEDGE.part_of AS
SELECT DISTINCT part, whole FROM (
SELECT e1.part, e1.whole FROM OAG_FABLE.KNOWLEDGE.part_of_edge e1
UNION ALL
SELECT e1.part, e2.whole FROM OAG_FABLE.KNOWLEDGE.part_of_edge e1 JOIN OAG_FABLE.KNOWLEDGE.part_of_edge e2 ON e1.whole = e2.part
) chains;
